from fractions import Fraction

def probes(*bounds):
    points = sorted(set(map(Fraction, bounds)))
    return ([points[0] - 1, points[-1] + 1] + points
            + [(left + right) / 2 for left, right in zip(points, points[1:])])

def f(x, a, b):
    p = 10 <= x <= 35
    q = 40 <= x <= 62
    A = a <= x <= b
    return A <= (p or q)

ends = sorted({10, 35, 40, 62})    # A лежит внутри одного из двух отрезков
lengths = []
for a in ends:
    for b in ends:
        if a <= b and all(f(x, a, b) for x in probes(10, 35, 40, 62, a, b)):
            lengths.append(b - a)
